#!/usr/bin/env python3
"""Require one documentation audit after Codex edits repository files."""

from __future__ import annotations

import json
import re
import sys
import tempfile
from pathlib import Path


def marker_path(session_id: str) -> Path:
    safe_id = re.sub(r"[^A-Za-z0-9._-]", "_", session_id)
    return Path(tempfile.gettempdir()) / "stockout-docs-audit" / f"{safe_id}.pending"


def main() -> None:
    payload = json.load(sys.stdin)
    marker = marker_path(str(payload.get("session_id", "unknown")))
    event = payload.get("hook_event_name")

    if event == "PostToolUse":
        if payload.get("tool_name") == "apply_patch":
            marker.parent.mkdir(parents=True, exist_ok=True)
            marker.write_text(str(payload.get("turn_id", "unknown")), encoding="utf-8")
        return

    if event != "Stop" or not marker.exists():
        return

    final_message = payload.get("last_assistant_message") or ""
    if "Docs: updated" in final_message or "Docs: no change" in final_message:
        marker.unlink(missing_ok=True)
        return

    if payload.get("stop_hook_active"):
        marker.unlink(missing_ok=True)
        return

    print(
        json.dumps(
            {
                "decision": "block",
                "reason": (
                    "Run $session-end now. Audit this implementation against the "
                    "matching local docs, update affected docs, and finish with exactly "
                    "one `Docs: updated ...` or `Docs: no change — ...` line."
                ),
            }
        )
    )


if __name__ == "__main__":
    main()

